import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp } from '../server.mjs'

// A data file in a fresh temp folder; cleanup() deletes the folder.
export function tempDataFile() {
  const dir = mkdtempSync(join(tmpdir(), 'split-test-'))
  return { file: join(dir, 'groups.json'), cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
export async function startApp(dataFile) {
  const server = createApp(dataFile)
  await new Promise((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', resolve)
  })
  const base = `http://127.0.0.1:${server.address().port}`
  return {
    call: (method, path, body) => request(base + path, method, body),
    stop: () => new Promise(resolve => server.close(resolve)),
  }
}

// Runs fn with a running app on its own data file, then stops it and deletes the file.
export async function withApp(fn) {
  const data = tempDataFile()
  const app = await startApp(data.file)
  try {
    await fn(app.call)
  } finally {
    await app.stop()
    data.cleanup()
  }
}

async function request(url, method, body) {
  const init = { method }
  if (body !== undefined) {
    init.headers = { 'content-type': 'application/json' }
    init.body = typeof body === 'string' ? body : JSON.stringify(body)
  }
  const res = await fetch(url, init)
  const text = await res.text()
  const isJson = (res.headers.get('content-type') ?? '').startsWith('application/json')
  return { status: res.status, headers: res.headers, text, body: isJson ? JSON.parse(text) : undefined }
}
// POST /groups/:id/import: records a list of expenses and payments in one go, all of them or none of them.
// Same contract as the other handlers: it returns a new store instead of changing the one it gets.
import { NOT_FOUND, findGroup } from './groups.mjs'
import { balances, expenseView, paymentView } from './ledger.mjs'
import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'

const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
const EXPENSE_FIELDS = ['type', 'description', 'payer', 'amount', 'split']
const PAYMENT_FIELDS = ['type', 'from', 'to', 'amount']
const MAX_ENTRIES = 50

const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v)

// Thrown by checkEntry with the first rule an entry breaks.
class Broken extends Error {
  constructor(rule) {
    super(rule)
    this.rule = rule
  }
}

// Runs one of the POST routes' parsers, turning its ValidationError into the import rule it stands for.
function parseAs(rule, parse) {
  try {
    return parse()
  } catch (err) {
    if (err instanceof ValidationError) throw new Broken(rule)
    throw err
  }
}

// The body's own checks, in order; the first one that fails is the 400 message. Returns the import options.
function parseImportBody(body) {
  const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
  if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
  const { entries } = body
  if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
    throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
  }
  const flag = name => {
    if (!Object.hasOwn(body, name)) return false
    if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
    return body[name]
  }
  return { entries, dryRun: flag('dry_run'), skipRecorded: flag('skip_recorded') }
}

// One entry's fields, checked by the same rules as POST /groups/:id/expenses or /payments. Throws Broken with
// the first field rule the entry breaks; duplicates are found later, by the caller.
function checkEntry(entry, group) {
  if (!isObject(entry)) throw new Broken('not-an-object')
  if (entry.type !== 'expense' && entry.type !== 'payment') throw new Broken('bad-type')
  const fields = entry.type === 'expense' ? EXPENSE_FIELDS : PAYMENT_FIELDS
  if (Object.keys(entry).some(key => !fields.includes(key))) throw new Broken('unknown-field')
  if (entry.type === 'expense') {
    return {
      type: 'expense',
      description: parseAs('bad-description', () => parseDescription(entry.description)),
      payer: parseAs('bad-payer', () => parseMember(entry.payer, group.members, 'bad payer')),
      amount: parseAs('bad-amount', () => parseAmount(entry.amount)),
      split: parseAs('bad-split', () => parseSplit(entry.split, group.members)),
    }
  }
  const from = parseAs('bad-from', () => parseMember(entry.from, group.members, 'bad from'))
  const to = parseAs('bad-to', () => parseMember(entry.to, group.members, 'bad to'))
  if (to === from) throw new Broken('bad-to')
  return { type: 'payment', from, to, amount: parseAs('bad-amount', () => parseAmount(entry.amount)) }
}

// Two expenses are the same when payer, amount in cents and description (trimmed, lower case) match.
const sameKey = ({ payer, amount, description }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])

export function importEntries({ state, params, body }) {
  const group = findGroup(state, params[0])
  if (!group) return NOT_FOUND
  const { entries, dryRun, skipRecorded } = parseImportBody(body)

  const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(sameKey))
  const seen = new Set()
  const problems = []
  const skipped = []
  const accepted = []
  entries.forEach((entry, index) => {
    let parsed
    try {
      parsed = checkEntry(entry, group)
    } catch (err) {
      if (err instanceof Broken) return problems.push({ index, rule: err.rule })
      throw err
    }
    if (parsed.type === 'expense') {
      const key = sameKey(parsed)
      const isDuplicate = seen.has(key)
      seen.add(key)
      if (isDuplicate) return problems.push({ index, rule: 'duplicate' })
      if (recorded.has(key)) return skipRecorded ? skipped.push(index) : problems.push({ index, rule: 'already-recorded' })
    }
    accepted.push(parsed)
  })
  if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }

  const expenses = []
  const payments = []
  for (const { type, ...fields } of accepted) {
    if (type === 'expense') expenses.push({ id: state.nextExpenseId + expenses.length, group: group.id, ...fields })
    else payments.push({ id: state.nextPaymentId + payments.length, group: group.id, ...fields })
  }
  const next = {
    ...state,
    expenses: [...state.expenses, ...expenses],
    payments: [...state.payments, ...payments],
    nextExpenseId: state.nextExpenseId + expenses.length,
    nextPaymentId: state.nextPaymentId + payments.length,
  }
  const reply = {
    status: dryRun ? 200 : 201,
    body: { expenses: expenses.map(expenseView), payments: payments.map(paymentView), skipped, balances: balances(next, group) },
  }
  // A dry run, or an import whose entries were all skipped, leaves the store and the data file as they are.
  return dryRun || accepted.length === 0 ? reply : { ...reply, state: next }
}

1	// Input checks for request bodies and query strings. Each parser returns the clean value or throws a
2	// ValidationError, which the server turns into a 400 reply.
3	
4	export class ValidationError extends Error {
5	  constructor(message) {
6	    super(message)
7	    this.name = 'ValidationError'
8	  }
9	}
10	
11	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
12	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
13	const MIN_MEMBERS = 2
14	const MAX_MEMBERS = 20
15	const MAX_GROUP_NAME_LENGTH = 100
16	const MAX_DESCRIPTION_LENGTH = 200
17	const CENTS_PER_UNIT = 100
18	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
19	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
20	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
21	
22	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
23	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
24	
25	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
26	
27	export function parseGroupId(v) {
28	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
29	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
30	  }
31	  return v
32	}
33	
34	export function parseGroupName(v) {
35	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
36	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
37	  }
38	  return v
39	}
40	
41	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
42	export function parseMembers(v) {
43	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
44	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
45	  }
46	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
47	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
48	  }
49	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
50	  return [...v]
51	}
52	
53	export function parseDescription(v) {
54	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
55	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
56	  }
57	  return v
58	}
59	
60	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
61	export function parseAmount(v) {
62	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
63	  // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
64	  const cents = Math.round(v * CENTS_PER_UNIT)
65	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
66	  return cents
67	}
68	
69	// A name that must belong to one of members; message says which field was wrong.
70	export function parseMember(v, members, message) {
71	  if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
72	  return v
73	}
74	
75	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
76	export function parseSplit(v, members) {
77	  if (v === undefined) return [...members]
78	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
79	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
80	  return [...v]
81	}
