1	// The data file: { groups, expenses, payments, nextExpenseId, nextPaymentId } as JSON.
2	import { readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
3	
4	export const emptyStore = () => ({ groups: [], expenses: [], payments: [], nextExpenseId: 1, nextPaymentId: 1 })
5	
6	const hasShape = data =>
7	  Array.isArray(data?.groups) &&
8	  Array.isArray(data.expenses) &&
9	  Array.isArray(data.payments) &&
10	  Number.isInteger(data.nextExpenseId) &&
11	  Number.isInteger(data.nextPaymentId)
12	
13	// Reads the store from file. A missing file is an empty store; a damaged file is an error.
14	export function load(file) {
15	  let text
16	  try {
17	    text = readFileSync(file, 'utf8')
18	  } catch (err) {
19	    if (err.code === 'ENOENT') return emptyStore()
20	    throw err
21	  }
22	  let data
23	  try {
24	    data = JSON.parse(text)
25	  } catch {
26	    throw new Error(`data file ${file} is not valid JSON`)
27	  }
28	  if (!hasShape(data)) throw new Error(`data file ${file} has an unexpected shape`)
29	  return data
30	}
31	
32	// Writes the store atomically: a temp file next to the target, then a rename over it.
33	export function save(file, data) {
34	  const tmp = `${file}.${process.pid}.tmp`
35	  writeFileSync(tmp, JSON.stringify(data, null, 2) + '\n')
36	  try {
37	    renameSync(tmp, file)
38	  } catch (err) {
39	    rmSync(tmp, { force: true })
40	    throw err
41	  }
42	}
